"""Build the independent temporal report from reviewed, field-allowlisted inputs."""
import argparse
from collections import Counter
import csv
from pathlib import Path
from analyze_rtt_90_180 import read_json, write_json, epoch, TARGETS
from write_rtt_90_180_report import stamp, num, COLORS, CLASS


def charts(project,data,inputs):
    points=read_json(data/'all-game-points-context.json')
    features=read_json(data/'point-control-features.json')
    old=project/'reports/evidence/rtt-90-180-2026-11-15/inputs'
    probes=[]
    for path in [old/'control-probes.csv',inputs/'additional-control-probes.csv']:
        with path.open(encoding='utf-8',newline='') as h:
            probes.extend(dict(r,rtt_ms=float(r['rtt_ms']) if r['rtt_ms'] else None) for r in csv.DictReader(h) if r['eligible']=='1')
    specs=[dict(name='open-all-points.png',title='All 291 logged Average Ping values: no upper-band exclusion',x_format='dd.MM HH:mm',
                x_label='UTC+05:00; absent records below 120 ms are not filled',y_label='Game Average Ping (ms)',y_min=80,y_max=400,
                series=[dict(name='Game threshold points only',color='#d62728',chart_type='Point',points=[dict(x=e['time_utc'],y=e['value']) for e in points])])]
    for name,start,end,ymax,title in [
        ('open-0058-complete.png','2026-11-13T19:58:03+00:00','2026-11-13T19:58:21+00:00',250,'Complete 00:58 sequence: 162.91 / 206.84 / 172.31 / 226.09 ms'),
        ('open-0007-quiet.png','2026-11-13T19:07:05+00:00','2026-11-13T19:07:30+00:00',230,'00:07: logged ~200 ms while measured ICMP controls stay low'),
        ('open-1536-complete.png','2026-11-13T10:36:18+00:00','2026-11-13T10:37:40+00:00',240,'Same connection :7149: 126.95 / 217.28 / 154.44 / 120.00 ms')]:
        lo,hi=epoch(start),epoch(end)
        series=[dict(name=t,color=c,points=[dict(x=r['sent_utc'],y=r['rtt_ms']) for r in probes if r['target']==t and r['status']=='Success' and lo<=epoch(r['sent_utc'])<=hi]) for t,c in zip(TARGETS,COLORS)]
        series=[s for s in series if s['points']]
        series.append(dict(name='Game threshold points; no interpolation',color='#d62728',chart_type='Point',points=[dict(x=e['time_utc'],y=e['value']) for e in points if lo<=epoch(e['time_utc'])<=hi]))
        specs.append(dict(name=name,title=title,x_label='UTC+05:00; ICMP lines measure different destinations',y_label='RTT (ms)',y_min=0,y_max=ymax,series=series))
    series=[]
    for c,color in [('C011','#d62728'),('Other connections','#1768ac')]:
        rows=[r for r in features if (r['connection_id']=='C011')==(c=='C011')]
        series.append(dict(name=c,color=color,chart_type='Point',points=[dict(x=r['far_minus_common_ms'],y=r['game_ms']) for r in rows]))
    specs.append(dict(name='open-tail-scatter.png',title='Tail-only correlation is driven by C011; no causal fit',x_numeric=True,
                      x_label='Nearest RETN excess minus common local excess (ms; fixed descriptive baselines)',y_label='Logged game Average Ping (ms)',y_min=110,y_max=180,y_interval=10,x_min=-5,x_max=150,series=series))
    lag=read_json(data/'lagged-control-window-overlap.json')
    specs.append(dict(name='open-lag-overlap.png',title='Lag sensitivity: overlap of event windows and abnormal control cycles',x_numeric=True,x_min=-12,x_max=12,x_interval=2,
                      x_label='Later controls at positive lag (seconds; 2-second cycle offsets)',y_label='Abnormal control cycles in shifted windows',y_min=0,y_max=20,
                      series=[dict(name='Dependent overlapping windows; descriptive only',color='#1768ac',points=[dict(x=r['control_lag_seconds'],y=r['bad_cycles']) for r in lag])]))
    ref=read_json(data/'control-alignment-shift-reference.json')
    specs.append(dict(name='open-shift-reference.png',title='5000 within-block circular shifts; observed overlap = 16',x_numeric=True,x_min=-.5,x_max=17.5,x_interval=2,x_interval_offset=.5,
                      x_label='Number of overlapping abnormal cycles; stationarity/boundary assumptions apply',y_label='Shift realizations (not independent observed incidents)',y_min=0,
                      series=[dict(name='Exploratory shifted reference',color='#1768ac',chart_type='Column',points=[dict(x=int(k),y=v) for k,v in ref['shifted_histogram'].items()]),
                              dict(name='Observed overlap: 16 cycles',color='#d62728',points=[dict(x=16,y=0),dict(x=16,y=max(ref['shifted_histogram'].values()))])]))
    minutes=read_json(data/'minute-control-series.json')
    series=[dict(name=t+' median',color=c,points=[dict(x=r['start_utc'],y=r['rtt_ms']['median']) for r in minutes if r['target']==t and r['rtt_ms']['n']]) for t,c in zip(TARGETS,COLORS)]
    specs.append(dict(name='open-minute-medians.png',title='Minute ICMP medians across saved coverage; no missing periods filled',x_format='dd.MM HH:mm',
                      x_label='UTC+05:00; line breaks at missing collection periods',y_label='ICMP RTT median (ms)',y_min=0,y_max=120,series=series))
    # Split lines at actual coverage gaps; do not draw artificial continuity across sessions.
    last=specs[-1];split=[]
    for s in last['series']:
        groups=[]
        for p in s['points']:
            if not groups or epoch(p['x'])-epoch(groups[-1][-1]['x'])>90:groups.append([p])
            else:groups[-1].append(p)
        split.extend(dict(s,name=s['name']+(f' part {i+1}' if i else ''),points=g,show_legend=i==0) for i,g in enumerate(groups))
    last['series']=split
    write_json(data/'chart-specs.json',specs)


def build(project):
    reports=project/'reports';data=reports/'rtt-open-data';inputs=reports/'evidence/rtt-open-2026-11-15'
    points=read_json(data/'all-game-points-context.json');conns=read_json(data/'connection-tail-process.json')
    summary=read_json(data/'summary.json');phase=read_json(data/'phase-exposure.json');ref=read_json(data/'control-alignment-shift-reference.json')
    replay=read_json(data/'classification-replay.json');audits=read_json(inputs/'INTEGRITY-AUDIT.json')
    aliases={s['file']:f'F{i+1}' for i,s in enumerate(read_json(inputs/'source-lineage.json')['frozen_game_sources'])}
    title='# Открытое исследование изменения игрового RTT Valorant, Meganet, 13–15 ноября 2026'
    lines=[title,'',
    'Это самостоятельный повторный анализ исходных игровых последовательностей, непрерывной телеметрии и методики прежних отчётов. Он не ищет заранее выбранного виновного. Время таблиц и графиков — **UTC+05:00**, машиночитаемые файлы содержат UTC. Число десятичных знаков в метке не означает независимую миллисекундную синхронизацию всех часов. Статические графики встроены в [HTML-версию](VALORANT-RTT-OPEN-INVESTIGATION.html).','',
    '## 1. Что удалось установить и что изменилось','',
    '**Единственную причину всех колебаний установить нельзя. Но объяснение «каждый игровой скачок вызван одинаковой общей перегрузкой Meganet/RETN» не соответствует наблюдениям.** Есть краткие общие всплески, есть игровой рост при спокойных контрольных направлениях и есть отдельные клиентские FPS/input-события. Они требуют разных проверок. Спокойный ICMP не доказывает исправность конкретного игрового UDP-пути и не назначает виновным Riot.','',
    '- Перепроверены **291** реальная числовая запись Average Ping из семи полных/зафиксированных игровых источников. 263 относятся к 120–180; **28 выше 180**. Полного ряда 90–119,99 нет. Ни разу не подставлен выдуманный RTT вместо отсутствующей записи.','',
    '- Обнаружена ошибка представления прежней хронологии: ограничение выборки сверху скрывало промежуточные значения **217,28** и **202,80**, а эпизод 00:58 включал также **206,84 и 226,09 мс**. Фильтр был корректен для подсчёта 263 точек, но непригоден для изображения полного эпизода. Исправлены прежний отчёт и его генератор; исторические ZIP остаются исходными срезами.','',
    '- Независимый повтор классификации всех 263 точек сохранил **58 QUIET / 13 с отклонениями / 192 без полного покрытия** при ±4 с. Это числа строк, не независимых происшествий и не доли игрового времени. Для всех 291: **69 QUIET / 6 LOCAL / 3 NEAR / 7 RETN / 206 без покрытия**.','',
    '- Порядок во времени важен: близость игровых предупреждений к контрольным отклонениям чаще, чем при сдвиге внутри тех же подключений. Но величина RTT не демонстрирует устойчивой общей зависимости от дальнего контроля: Pearson 0,449 для дальнего остатка становится −0,049 после исключения C011; Spearman всего 0,029. Это против вывода о едином количественном механизме для всей выборки.','',
    '- Найдено дополнительное противонаблюдение: **14.11 00:07:16 — около 200 мс в игре при спокойных доступных контролях**. Игра после одного IP может ухудшаться и частично восстанавливаться без travel/restart; обязательная смена IP для такого колебания не нужна.','',
    '- Проверены фазы раундов, агрегаты frametime, предупреждения подгрузки ресурсов и часы измерителя. Устойчивой общей привязки RTT к границам раундов или resource-hitch предупреждениям не найдено. Сборщик продолжает работать; новые игровые сессии, ping/tracert, нагрузочные тесты и захват пакетов не запускались.','',
    '![Все 291 числовая запись, без верхнего отсечения](figures/open-all-points.png)','',
    '## 2. Данные, происхождение и границы покрытия','',
    '| Источник | Использование и ограничение |','|---|---|',
    '| RRT и оригинальные ShooterGame | Четыре совпадающих RRT/local источника учитываются однократно; три локальных файла добавляют отсутствующие в RRT периоды. Полные оригиналы остаются вне Git |',
    '| Семь frozen игровых файлов | SHA-256 и номер строки для каждого извлечённого события. Проверена неизменность соответствующих префиксов текущих оригиналов; в дописанном хвосте нет новых Average Ping/ClientTravel/Browse строк |',
    '| Предыдущие reviewed numerical inputs | 110495 ICMP-строк, 109805 пригодных; 690 известным образом ошибочных исключены из сетевых выводов. Сохранены все причины исключения |',
    f"| Новый committed prefix того же работающего монитора | Ещё **27690** probe-строк без повторения старых seq; общий пригодный ICMP массив **{summary['qualified_controls']}**, последняя отправка **{stamp(summary['control_end_utc'])}**. Продолжение ночного контроля, а не новые игровые измерения |",
    '| Ручные записи | F8/F9, отдельные сообщения и скриншот; кнопка не измеряет RTT, время ответа в чате не равно времени начала скачка |',
    '| Системные данные | Прежние 1548 обезличенных снимков Wi-Fi/счётчиков/маршрутов, новый snapshot delta, сохранённая выборка Windows событий; отсутствие записи не доказывает отсутствия короткого сбоя |',
    '| Ping/tracert и CS2 | Завершённый пакет команд читается как отдельное измерение, не подменяет синхронный игровой RTT; Valve relay не считается физическим матч-сервером |','',
    'Пригодные данные непрерывного сборщика пересмотрены до конкретного committed seq, а не до произвольной последней строки открытого файла. Активный run зафиксирован на **126931**, старый срез был **98771**. В новом delta нет дубликатов старого префикса. Для старых завершённых runs caps 3299 и 5988. Нет команды остановки или перезапуска. Публикация — срез, GitHub не является live-трансляцией.','',
    'Состав, хеши и водоразделы: [source-lineage](evidence/rtt-open-2026-11-15/source-lineage.json), [границы monitor](evidence/rtt-open-2026-11-15/monitor-boundaries.json), [аудит оригинальных префиксов](evidence/rtt-open-2026-11-15/INTEGRITY-AUDIT.json). Прежняя [инвентаризация RRT](RIOT-RRT-LOG-ANALYSIS.md) и [таблица 263 точек](VALORANT-RTT-90-180-ANALYSIS.md) сохраняют подробности; новый разбор не считает их непререкаемыми.','',
    '| Обозначение | Источник |','|---|---|']
    for file,label in aliases.items():lines.append(f'| {label} | `{file}` |')
    lines += ['', '## 3. Что действительно представляет временной ряд','',
    'Имеются **пороговые сообщения**, а не равномерная выборка Network RTT. Минимальное записанное Average Ping — 120,00, максимальное — 383,31 мс. В строках явно указаны Threshold 120,00 для 270 обычных сообщений и Threshold 200,00 для 21 «critically exceeded»; категория лога у обоих Error. Распределение ниже условно на срабатывание logger; медиана около 125 не означает, что большую часть матча пинг был 125. Сглаживание, повторная выдача, частота проверки и возможный гистерезис не документированы для данной сборки. Три равные последовательные пары могут быть повторной выдачей/округлением; это не три независимых сетевых эксперимента.','',
    '| Записанный диапазон, мс | Число строк |','|---|---:|',
    '| 120–<130 | 214 |','| 130–<150 | 40 |','| 150–180 | 9 |','| >180–<200 | 7 |','| 200–<300 | 13 |','| ≥300 | 8 |','',
    'Из 160 последовательных пар одного подключения с расстоянием не более 10 с медиана модуля изменения **4,185 мс**, p95 **34,53**, максимум **90,33**. Эти числа описывают изменения между сохранёнными threshold точками, а не непрерывную скорость роста. Встречаются движения вверх и вниз, включая возврат из 200+ в 150–180; единого монотонного сценария нет.','',
    'Группировка точек по разрыву 5/10/30/60 с даёт **181 / 131 / 61 / 50** групп. Различие почти в четыре раза показывает, почему нельзя объявить количество warning строк количеством отдельных сетевых аварий. Размах времени от первой до последней точки — support span, не доказанная продолжительность высокого RTT. Все continuous_duration_seconds оставлены null.','',
    'Ни HMM, ни change-point, ни спектр «периодического пинга» здесь не дают надёжных состояний 90/100/110: вход цензурирован и нерегулярен, отсутствуют значения и знаменатель времени в состояниях. Вычислять частоту/периодичность из интервалов выдачи Warning означало бы смешать работу logger с физикой сети. [Полные короткие переходы](rtt-open-data/logged-point-transitions.json), [группы по 10 с](rtt-open-data/point-clusters-10s.json).','',
    '## 4. Подключения и вариации внутри них','',
    'В таблице min/median/max рассчитаны **только по сохранённому хвосту ≥120**. Ни один показатель не является baseline матча. `0` означает отсутствие threshold строки, не гарантирует нормальное соединение. Порт — удалённый, привязанный travel/map-ready/NetDriver контекстом; это не локальный ephemeral port. Публичный IP не устанавливает физическую площадку или маршрут конкретного UDP-пакета.','',
    '| Conn | IP:порт | Начало → конец +05 | N | Условные min / median / max, мс | Первая threshold после MapReady, с |','|---|---|---|---:|---|---:|']
    for c in conns:
        q=c['tail_rtt_ms'];stats=' / '.join(num(q.get(k)) for k in ['min','median','max'])
        lines.append(f"| {c['connection_id']} | {c['ip']}:{c['port']} | {stamp(c['start_utc'])} → {stamp(c['end_utc'])} | {c['n']} | {stats} | {num(c['first_ping_after_map_ready_seconds'])} |")
    lines += ['',
    'Первый порог появляется и через **6,604 с** после MapReady (C003), и через **1190,802 с** (C001). Поэтому рост RTT нельзя объяснить исключительно обязательной задержкой при загрузке карты. Сравнивать N между соединениями как долю плохого времени нельзя: различаются длина подключения, число раундов, режим, время суток и полнота игровой серии.','',
    'C002 содержит 139 точек от 120 до 217,28 на одном :7149. C011 — девять от 120,74 до 226,09 на одном :7354. C015 — 155,46 и позднее 121–126 на одном :7216; рядом пользователь подтвердил низкий диапазон 85–93 без числовой привязки к каждой F9. Эти наблюдения опровергают необходимость смены публичного IP/порта для каждой вариации. Они не исключают смену внутреннего пути/ECMP/обратного маршрута при неизменном адресе.','',
    'После перезапуска 14 ноября C012 `185.40.64.1:7004` сменилось C013 `162.249.72.1:7004`, снизился сообщённый RTT. Одновременно изменились процесс, соединение, время, возможные NAT/ingress и состояние клиента. Это полезный естественный эксперимент с несколькими изменившимися факторами, но не изоляция эффекта адреса. Привязка к тому же матчу не означает тот же ingress и не доказывает смену физического backend.','',
    '## 5. Исправленная хронология и новые контрпримеры','',
    '**13 ноября 15:36, C002 :7149.** Полная последовательность: 126,95 в 15:36:24.702 → **217,28 в 27.869** → 154,44 в 28.444 → 120,00 в 15:37:35.253. Интервалы 3,167 / 0,575 / 66,809 с. Ранее запись 217,28 ошибочно исчезла из иллюстрации последовательности из-за фильтра. ICMP тогда не собирался; нельзя назначить виновным домашнюю сеть, Meganet или Riot.','',
    '![Полная последовательность 15:36, без ICMP-покрытия](figures/open-1536-complete.png)','',
    '**13 ноября 15:43 и 15:59, то же C002.** 15:43:25.305–28.467 есть 195,45–207,62; в начале рядом Burst Loss. Позднее 161,09 в 29.051 и 127,26 в 36.944 — частичное снижение среди сохранённых точек, а не точно установленная длительность восстановления до нормы. В 15:59:06.735–19.872 снова 191,35–206,55. Так в одном подключении повторяются отдельные серии; их нельзя свести к единственному isolated spike. Пригодных одновременных контролей нет.','',
    '**13 ноября 22:26, C003 :7125.** 129,34 в 44.304 → 152,95 в 45.699 → **202,80 в 48.233** → 161,94 в 48.737 → 138,97 в 22:27:37.164 → 127,44 в 58.217. Предыдущая таблица пропускала 202,80. Переходы не заполнены интерполяцией; ICMP отсутствует.','',
    '**14 ноября 00:03–00:07, C007 :7039.** Пользователь сообщил высокий RTT, скриншот показывает 185/189 avg/max и накопленные 48 lost packets при текущем 0%. В старой серии действительно был пробел 00:03:21–00:06:13; новая игравая threshold точка 152,67 в 00:04:34.283 не восстанавливает отсутствующий ICMP. Но **00:07:16.121 и .134 — 201,70**, .626 — **198,45**, уже при пригодных контролях ±4 с ниже лимитов. Это три строки, включая повтор равного значения через 13 мс, а не три независимых инцидента. Новое наблюдение ограничивает версию о необходимом общем ICMP-всплеске для повышенного игрового RTT.','',
    '![Около 200 мс в игре при спокойных контролях 00:07](figures/open-0007-quiet.png)','',
    '**14 ноября 00:55, C011 :7354.** В 00:55:30.012 Average Ping 183,84 совпадает с локальным классом окна. Позднее в 44.503 / 46.245 / 48.589 — 122,80 / 134,64 / 131,32; есть общий цикл порядка GW/near/CF/RETN1/RETN2 **140/140/160/279/279**. Одновременный рост до шлюза и дальних целей поддерживает общий локальный/доступовый/планировочный компонент конкретного эпизода. Он не локализует Wi-Fi против AP, драйвера или host scheduling и не объясняет все другие случаи.','',
    '**14 ноября 00:58, тот же :7354.** Полный ряд: **162,91 в 09.942 → 206,84 в 10.737 → 172,31 в 11.966 → 226,09 в 14.554**. До этого контролям соответствуют примерно 2/3/24/93/92; в 09.969 — 11/13/34/150/150, в 11.956 — 8/10/30/180/180, в 13.946 — 1/19/23/178/178; в 15.930 снова 2/2/25/93/92. Это смешанное совместное ухудшение, а не изолированный скачок только RETN или только игры. Более поздние игровые точки классифицированы NEAR из-за near=19; приоритет класса скрывает одновременные RETN-превышения, поэтому классы не следует читать как взаимоисключающие причины.','',
    'Величина роста игры находится рядом по времени с дальним ростом, но приложение может сглаживать RTT; самая высокая игровая точка позже контрольного максимума. Одна такая последовательность не определяет ни точное причинное запаздывание, ни конкретный участок. В ±4 с этих четырёх точек нет соответствующих FPS/loss/input warnings. Контроли восстановились в 15.930; точная секунда восстановления игры неизвестна.','',
    '![Полная последовательность 00:58 до 226 мс и контрольные направления](figures/open-0058-complete.png)','',
    '**14 ноября дневной матч.** Уточнение владельца **95→120→180→120**, позднее 300–400, относится к неоднократным колебаниям. Точные секунды этих четырёх ручных уровней неизвестны. 107 F8 и 20 F9 дают 21 группу нажатий (20 закрыты, одна открыта); частые F8 около 14:19–14:22 отражают колебания 120–180 по пояснению игрока, а не 107 отдельных измеренных пиков. В отчёте не назначены секунды числам по ближайшей кнопке.','',
    '**14:27:45.760–14:29:58.816** — восемь числовых 328,12–383,31 на :7004, 26 input-stop/overflow в исследованном критическом окне. Прежние **335/335** успешных контролей за эпизод и медианы **2/3/24/93/92** подтверждаются исходным отдельным анализом. Это не означает, что игра была высокой все 133,056 с между первой и последней threshold строкой; пользователь независимо сообщил около пяти минут. Игровой UDP, обратный путь и обработка клиента/сервера не контролировались этими ICMP.','',
    '**После перезахода** пользователь сообщил 100–110, поздние F8 — 120–130. 14:35:10.445 (125,63) и 14:48:12.467 (125,62) близки к FPS/input событиям, но большинство точек не имеет такого совпадения. В 14:48 local FPS 2,5/6,78 за 106/76 мс и input-stop/overflow за 3 мс до ping warning: это сильное временное совпадение обработки клиента, не установленное направление причинности.','',
    '**15 ноября 01:08:44.282**, C015 :7216 — **155,46**, GW 1–2 / near 2–4 / CF 25–27 / RETN 91–93 в ±4 с, без FPS/loss/input warning в таком окне. F9 в 01:09:22.333 на **38,051 с позже**. Сообщённые 85–93 относятся к двум F9 в разных матчах в целом; это не измеренная секунда восстановления. В этом же C015 позднее 01:13:33.911 / 43.192 / 49.776 — 121,63 / 125,89 / 120,02.','',
    '**15 ноября 01:28:46.934**, C016 :7102 — вторая F9 с общим сообщённым диапазоном 85–93. В 01:31:34.092 отдельный цикл содержит четыре ICMP-тайм-аута при отвечающем RETN2 около 92. Соседней игровой threshold строки нет. Это контрпример превращению любого контрольного отклонения в доказанный игровой скачок; отсутствие строки не доказывает низкий игровой RTT.','',
    '[Отдельная хронология с UTC, +05, границами точности](VALORANT-RTT-OPEN-CHRONOLOGY.md) и [все 291 контекста](rtt-open-data/all-game-points-context.json).','',
    '## 6. Совпадение с контролями: устойчивость и контрпримеры','',
    'Классификация ±4 с использует все пробы окна, минимум две на каждую из пяти целей, статусы и заранее сохранённые лимиты: GW≥15 / near≥16 / CF≥38 / RETN238≥109 / RETN233≥106; ранний RETN234≥100 мс. Иерархия GW→near→CF→RETN — описание наблюдения, не алгоритм установления виновного. Максимумы разных целей внутри окна могут принадлежать разным циклам. Для проверок одновременности использованы отдельные полные циклы.','',
    'Для 263 выбранных точек окна ±1/2/4/10 с дают спокойные **63/60/58/48**. Рост числа совпадений при расширении окна ожидаем и сам по себе не подтверждает причину. Среди девяти выбранных 150–180 точек шесть без контролей, две — C011 с дальним ростом, одна — C015 со спокойными контролями. Новая полная выборка показывает, что целевой band не исчерпывает ни тяжесть, ни структуру эпизодов.','',
    'Ранее 16 аномальных циклов из 223 около выбранных событий сравнивались с 58 из 3319 прочих циклов во время подключений. Это **7,17% против 1,75%**, но прочие циклы не размечены как «нормальная игра». Соседние пробы и повторяющиеся warning зависимы. Простая независимая binomial/Fisher интерпретация была бы чрезмерно сильной.','',
    'Новая проверка сохраняет целиком сгруппированную маску ±4 с относительно warning, отдельно в каждом непрерывном блоке **того же conn/source**, и циклически сдвигает её относительно контрольных аномалий. Блоки <30 циклов и без событий не участвуют; разрывы >3 с разделены. Сдвиги от 10 циклов до n−10 исключают почти исходное совмещение. **5000** воспроизводимых реализаций, seed 20261115; 9 блоков / **2769** циклов / 223 отмеченных окна.','',
    f"Наблюдается **16** пересечений; в сдвинутой reference медиана **{ref['shifted_counts']['median']:g}**, p95 **{ref['shifted_counts']['p95']}**, максимум **{ref['shifted_counts']['max']}**, среднее **{ref['shifted_mean']}**. Tail fraction с поправкой +1 — **{ref['reference_tail_fraction']:.6f}**. Это исследовательская мера необычности совмещения при предположениях стационарности внутри блока и циклической границы; **не вероятность виновности, не причинный p-value и не подтверждающий тест с заранее зарегистрированной гипотезой**. Мы проверяем несколько паттернов и не объявляем поправку на все исследовательские решения.", '',
    'После исключения C011 остаётся 10 пересечений, reference p95=7, tail fraction≈0,00550; следовательно, факт близости событий не целиком создаётся одним 00:58. Однако другие блоки иерархически смешивают LOCAL/NEAR/RETN и обработку клиента; это не выделяет транзит. Без C013 — также 10 пересечений, p95=7. Все leave-one-connection-out результаты опубликованы, а не только выгодный пример.','',
    '![Исследовательская reference при сохранении кластеров](figures/open-shift-reference.png)','',
    'Описательная lag-проверка для сдвига окон −10/−6/−4/−2/0/+2/+4/+6/+10 с даёт **9/10/14/16/16/15/13/9/2** аномальных цикла. Максимум широк около нуля, а соседние окна перекрываются. Это поддерживает близость по времени, но не определяет, что именно предшествует чему на уровне миллисекунд. Сдвиг делается на целые 2-секундные циклы; для этого анализа нельзя заявлять субсекундное запаздывание.','',
    '![Проверка сдвига контрольных окон](figures/open-lag-overlap.png)','',
    'Дополнительно взяты ближайшие RTT для 71 покрытой band-точки. Описательный общий ближний остаток — median(GW−2, near−3, CF−23), дальний — median(RETN238−93, RETN233−92); их разность уменьшает общий локальный компонент, но **не является задержкой физического участка**: адреса и обратные пути разные. Pearson(game, far−common)=**0,448745**, Spearman=**0,029340**. После исключения C011 Pearson=**−0,049375**, Spearman=**−0,112694**. У самого дальнего остатка Pearson 0,313, Spearman 0,021. Значит, видимая линейная связь величин в основном опирается на отдельный leverage-эпизод, а не на устойчивый монотонный закон во всей цензурированной выборке.','',
    '![Корреляция хвоста: роль отдельного подключения C011](figures/open-tail-scatter.png)','',
    'Центрирование каждой величины внутри своего подключения дополнительно снижает Pearson дальнего остатка до −0,006, far−common до 0,181; Spearman −0,127 и −0,053. Это подчёркивает влияние различий между соединениями и редких крупных точек. Центрирование не устраняет цензурирование и зависимость соседних записей. Выводы «аномалии иногда близки во времени» и «рост игрового RTT пропорционален росту RETN» различаются. Первый выдерживает эту ограниченную проверку, второй — нет. Опубликованы [reference и LOCO](rtt-open-data/control-alignment-shift-reference.json), [lag](rtt-open-data/lagged-control-window-overlap.json), [корреляции](rtt-open-data/tail-correlations.json) и [исходные 71 feature rows](rtt-open-data/point-control-features.json).','',
    '## 7. Новые объяснения: фазы раундов и состояние клиента','',
    'Из полных исходников извлечены **137 Gameplay(server time=0)**, **151 Gameplay(nonzero)**, **141 OnRoundEnded**, **94 asset-preload warnings**, **17 configured tickrate**; дополнительно **846** числовых метрик из 141 per-round performance summaries. Поля local/server game time — относительное игровое время; их разность нельзя читать как UDP RTT, one-way latency или рассинхронизацию Windows. Configured tickrate не измеряет фактические server-tick stalls.','',
    '| Событие | Окно | Ping строк рядом / 291 | Доля строк | Доля времени подключения в объединении окон |','|---|---:|---:|---:|---:|']
    for p in phase:
        lines.append(f"| {p['kind']} | ±{p['window_seconds']} с | {p['point_hits']} | {100*p['point_hits']/291:.2f}% | {100*p['exposure_seconds']/p['total_connection_seconds']:.2f}% |")
    lines += ['',
    'Окна обрезаны MapReady→NetDriver end и объединены; общий наблюдаемый интервал подключений **18234,995 с**. Доли — диагностика плотности logger, не независимый rate-ratio тест: разные матчи имеют разную интенсивность предупреждений и фазы пересекаются. На ±10 с Gameplay-zero находятся 41/291=14,09% строк при 15,03% временного покрытия, round-end 14,09% при 15,41%. Общего обогащения около этих границ нет. На ±1 с локально есть 9/291 против 1,50% экспозиции; это малый, зависимый и неустойчивый эффект. После исключения C012: 7/257 против 1,46% времени на ±1; на ±10 — 33/257 против 14,61% времени. Это не устойчивое доказательство «раунд вызывает пинг».','',
    'В критическом эпизоде есть конкретная последовательность: **14:27:43.702 round 11 end → 44.273 Gameplay-zero → 44.657 input-stop → 45.760/46.264 ping 348/383**; затем **14:29:02.315 round 12 end → 02.676 Gameplay-zero → 02.688/03.134 ping 374/369**. Но другие высокие точки в 14:28:54 и 14:29:58 не ограничены этими границами. Возможны reset/возобновление обработки или выдачи предупреждений при смене фазы, а не начало физической задержки на этой секунде. Чтобы различить это, нужен непрерывный RTT и схема logger от Riot; один порядок сообщений не доказывает механизм.','',
    '94 предупреждения «asset not preloaded / hitching» не совпадают с ping-точками в ±1 или ±5 с; в ±10 с совпала одна строка. Это ослабляет механизм, при котором **каждый** подъём RTT объясняется именно этим типом asset hitch. Предупреждение — о риске подгрузки, не измеренный stall; отсутствие его не исключает другие CPU/GPU/I/O/driver паузы.','',
    'Агрегированные frametime перед границами критических раундов: **11,52** мс около 14:27:43.700 и **6,26** мс около 14:29:02.314; Avg. Engine Latency **9,08 / 7,79**. Это per-round means, не одновременный сетевой RTT и не доказательство отсутствия коротких локальных зависаний. «Engine Latency» в performance summary не подменяет Network RTT. Мгновенные FPS threshold совпадения остаются отдельным меньшинством: среди 263 точек 2/3/12 при ±1/4/10 с; ни одна из девяти band-точек 150–180 не имеет FPS warning в ±4 с.','',
    'Историческая документация Riot описывает задержку обработки и адаптивное buffering после jitter/low FPS, но также подчёркивает, что некоторые buffering delays **не отражались в Network RTT Avg/Max и scoreboard**; изменения внесены в 4.10 в 2022 году. Поэтому нельзя сослаться на старый buffering bug как доказанную причину измеренных Network RTT в 2026. Проверяемая современная гипотеза — различить wire RTT, processing delay и фактическую задержку ACK/обработки; для этого нужны определения и текущая телеметрия Riot. [Официальное объяснение 2022](https://playvalorant.com/en-us/news/game-updates/valorant-gameplay-consistency-update-2/), [patch 4.10](https://playvalorant.com/en-gb/news/game-updates/valorant-patch-notes-4-10/).','',
    'Логирование не содержит найденного непрерывного числового ряда Network RTT+Processing Delay/Jitter, данных client focus/alt-tab, DPC/ISR или реальной server-tick latency. Мы не приписываем пользователю alt-tab и не объявляем известную старую ошибку актуальной. [Фазы](evidence/rtt-open-2026-11-15/phase-events.json), [performance aggregates](evidence/rtt-open-2026-11-15/performance-summaries.json), [ближайшие фазы всех точек](rtt-open-data/all-291-points-phase-context.json).','',
    '## 8. Аудит измерителя, часов и пробелов','',
    'Нативный collector читает IcmpSendEcho2 RoundTripTime; cumulative elapsed_ms служит монотонным временем от начала run, **не RTT**. Его нельзя подставлять в график задержки. Поля Address/Status/RoundTripTime — первые три 32-bit ULONG/DWORD с offsets 0/4/8. На этой Windows проверен layout синтетическим буфером без вызова API. По Microsoft 64-bit IcmpSendEcho2 использует ICMP_ECHO_REPLY32: неиспользуемые trailing pointer fields текущей ctypes модели требуют отдельной аккуратной ревизии в будущем, но читаемый 12-byte prefix имеет правильные offsets. Оснований объявить нативные RTT недействительными по этой причине нет. [IcmpSendEcho2](https://learn.microsoft.com/en-us/windows/win32/api/icmpapi/nf-icmpapi-icmpsendecho2), [структура REPLY32](https://learn.microsoft.com/en-us/windows/win32/api/ipexport/ns-ipexport-icmp_echo_reply32). Работающий collector не изменён.','',
    '| Run | Проверенные seq | Контроль wall−monotonic, min/max мс | Max first-sent cycle gap, с | Max completed→record delay, мс |','|---|---:|---|---:|---:|']
    for a in audits['monitors']:
        ex=a['wall_minus_monotonic_extrema']
        lines.append(f"| {a['source']} | {a['last_seq']} | {ex[0]['residual_ms']:.3f} / {ex[1]['residual_ms']:.3f} | {a['first_sent_cycle_gap_seconds']['max']:.3f} | {a['largest_write_delay']['delay_ms']:.3f} |")
    lines += ['',
    'В трёх пригодных continuous префиксах проверены seq без пропусков/дубликатов и SHA точных байтов; вращение файлов не создаёт разрыва сессии. Для живого run единственный cycle gap >2,5 с — 2,736; нет исчезнувших 10-минутных периодов внутри этого непрерывного префикса. Времена sent могут идти не по порядку seq из-за параллельного завершения пяти проб; сравнивать нужно по sent_utc/cycle, не считать каждую перестановку корректировкой часов.','',
    'Wall−monotonic у дневного 300-мс эпизода остаётся в пределах примерно −0,4…+0,6 мс. В текущем run отдельные residual до −28,078 мс быстро возвращаются (01:12:36 +05); это может включать планирование между чтением wall и monotonic, а не подтверждённый NTP step. Максимальные задержки записи — 172/146/237 мс. Поэтому сопоставление ведётся по **sent_utc/game event time**, а не по времени появления строки на диске. Аудит не обнаруживает минутного сдвига, который объяснил бы стабильные ICMP при многоминутном игровом 300–400. Он не доказывает независимую синхронизацию game/server clocks с точностью 1 мс.','',
    'Native wait−RTT у Success имеет median≈1,25–1,28 мс, p95<2 мс; отдельные максимумы до 149 мс показывают возможную задержку возврата/планирования. Это ещё один повод не выдавать Python elapsed wait за wire RTT. Success без RTT нет. Известные ранние дефектные серии по-прежнему не включаются; история пробела 00:03–00:06 сохранена, а не «исправлена» данными более позднего мониторинга.','',
    '[Нативный аудит](evidence/rtt-open-2026-11-15/native-clock-audit.json) и [целостность/cadence](evidence/rtt-open-2026-11-15/INTEGRITY-AUDIT.json).','',
    '## 9. Wi-Fi, нагрузка, маршруты и время суток','',
    'Прежние снимки, реально близкие к игровым точкам, показывают AP-01, канал 36, RSSI −65…−53 dBm; все 1548 снимков connected, errors/discards без прироста. Для 71 покрытой band-точки средние интервальные RX≤1,216 и TX≤0,646 Мбит/с. Это не подтверждает насыщение канала именно трафиком ПК. В общем локальном эпизоде 00:55 контролям стало хуже даже до шлюза; такой вклад не следует игнорировать только потому, что во многих других случаях ICMP тихий.','',
    'Нет пер-пакетных Wi-Fi retries/airtime/queue occupancy, загрузки других устройств и коротких burst; долгий средний интервал может скрыть очередь. Router CPU/радиоканал/драйвер/host scheduling не разделены. Windows route snapshots отличаются InterfaceMetric 30/35, но сохраняют ifIndex 7/тот же gateway для контролей. Это не доказательство ECMP/BGP изменения или игрового VPN-пути. Сохранённые Windows сетевые события не дают синхронной ошибки адаптера/DNS для выбранных ping-точек, однако журнал не является непрерывным аппаратным трассировщиком.','',
    'Новые почасовые ICMP распределения по **всему пригодному покрытию**, включая продолжение ночи: gateway hourly median всегда 2, near 3–4, Cloudflare 23–26, RETN238 93–95, RETN233 92–93, ранний RETN234 85 мс. Наибольшие hourly p95 соответственно 6/8/31/102/97/90. Это не выглядит как длительное общее повышение всех контрольных маршрутов на десятки–сотни мс. Но часовые медианы скрывают короткие spikes и смешивают разную полноту часов. Нельзя переносить их на игровой UDP.','',
    '![Минутные ICMP-медианы; разрывы сбора не соединены](figures/open-minute-medians.png)','',
    'Дневные и ночные threshold записи присутствуют, но игровое покрытие и идентичность backend различны, часть 13 ноября не имеет контролей. Статистически отделить час суток от игры/сервера/длительности/режима невозможно. Нет основания объявить «вечернюю перегрузку Meganet» или повторяющийся периодический таймер. [Поминутные числа](rtt-open-data/minute-control-series.json), [почасовые min/median/p95/max/N](rtt-open-data/hourly-control-distributions.json).','',
    'Завершённые traceroute к двум Riot адресам заканчиваются отвечающими RETN-интерфейсами, а обе цели не отвечают на 100 ICMP echo. Это ограничение измерения, не 100% игровых потерь. Трассы выполнены после дневного критического эпизода. Старый однократный hop около 70 мс и текущие медианы RETN около 92–95 — разные адреса/времена/ответные пути, без повторного синхронного контекста их нельзя превратить в доказанную смену международного маршрута. CS2 relay 72–81 мс показывает доступность другого Valve направления в отдельном тесте, а не здоровый физический Stockholm backend Valorant. [Полный неизменённый пакет](meganet-package-2026-11-14/README.md).','',
    '## 10. Проверка гипотез и различающие наблюдения','',
    'Confidence ниже относится к поддержке механизма наблюдениями, а не к вероятности вины организации. Ни одна версия не объясняет доказанно все классы эпизодов. [Отдельный перечень проверок](VALORANT-RTT-OPEN-HYPOTHESES.md) даёт владельца данных и ожидаемый опровергающий результат.','',
    '| Гипотеза | Что поддерживает | Контрпример / ограничение | Текущий вывод |','|---|---|---|---|',
    '| Общий локальный/доступовый краткий stall | GW и дальние цели вместе растут 00:55; отдельные LOCAL окна | 69 полных игровых окон при низких контролях, в том числе 300+ и 155 | Средняя уверенность в существовании локального компонента отдельных случаев; источник внутри LAN/host не локализован |',
    '| Общий дальний маршрут/очередь/транзит | Полный 00:58 эпизод до 226 рядом с двумя RETN rises; reference совмещения | Ближние тоже растут, ICMP другой, величинная связь исчезает без C011 | Средняя для конкретного совместного дальнего паттерна; низкая для общей причины и конкретного оператора |',
    '| Специфический UDP forward/reverse, NAT/ECMP/QoS или ingress | Тяжёлый и 155-мс эпизоды без общих контролей; смена адреса при rejoin | Нет наблюдения пути/потоковых очередей; тот же IP тоже даёт колебания | Совместимо и существенно не проверено; нужны двусторонние flow данные |',
    '| Клиент/сервер задерживает ACK/сетевую обработку | Input-stop/overflow критического периода, отдельные FPS coincidences, rejoin reset | 150–180 обычно без FPS warnings; input события могут быть следствием, не причиной | Средняя для наличия обработочных симптомов, низкая для происхождения RTT |',
    '| Переходы фаз раунда/особенность выдачи logger | Два onset-подобных critical warning рядом с Gameplay-zero | Большинство точек вне фаз; ±10 доля не выше времени; другие critical вне границ | Новая, слабая; не общий механизм. Различить logger reset и физический spike |',
    '| Asset streaming вызывает все RTT spikes | В логах 94 resource-hitch предупреждения | 0 совпадений ±5 с; только 1 на ±10 с | Конкретная универсальная версия ослаблена; другие локальные stalls не исключены |',
    '| Насыщение/очереди от фоновой нагрузки | Возможны bursts, другие устройства и QoS различия | Средний трафик ПК низкий, queue/airtime отсутствуют | Не подтверждено, не исключено; speed test во время игры не нужен |',
    '| Ошибка измерителя/часов создаёт всё расхождение | Известны старые дефектные серии, нативная и Python wait различны | Они исключены; проверенный prefix, native RTT, cadence и часы дневного run не дают минутного сдвига | Универсальная версия не поддержана; остаточная точность/сглаживание остаются ограничениями |','',
    '## 11. Доказанные факты, закономерности, гипотезы, неизвестное и новые открытия','',
    '**А. Доказанные факты.** 291 пороговая строка с time/file/line; 17 соединений; внутри одного подключения есть рост и снижение; проверенные отдельные игры/контроли расходятся; известные capture gaps и 690 ошибочных проб не замаскированы. Точные все 263 классификации воспроизведены. Packet-loss предупреждения и input overflow присутствуют, но общего непрерывного игрового процента потерь нет.','',
    '**Б. Повторяющиеся наблюдения.** Несколько серий повышений/частичных снижений на одном IP/порту, а не единственная эскалация 95→400. Краткие общие ICMP всплески бывают; игровые warnings бывают и без них. Близость событий к контрольным отклонениям сохраняется при внутриподключенческом сдвиге, но не означает единую количественную зависимость величин.','',
    '**В. Рабочие гипотезы.** Общий локальный компонент части событий; дальний общий компонент 00:58; game-flow-specific путь/обратное направление/NAT/ingress; клиентская/серверная обработка и особенности RTT/logger. Привязка к фазам и asset streaming проверены как альтернативы, не приняты как готовое объяснение.','',
    '**Г. Неизвестное.** Истинный RTT 90–119,99 по секундам, точные начало/конец большинства уровней, определение/окно Average Ping logger, реальные one-way UDP delays, drop/reorder/jitter по направлениям, ingress/backend mapping, состояние очередей/airtime и временные тики сервера. Нет сопоставимой Beeline серии.','',
    '**Д. Новые открытия.** Пропущенные верхним фильтром промежуточные пики; новый 00:07 игровой ~200 при тихих контролях; leverage-зависимость Pearson против почти нулевого Spearman; кластер-сохраняющая проверка совпадений и lag; отрицательные результаты фаз/asset-preload; аудит clock/monotonic/write delay и отсутствие минутного сдвига измерителя. Эти результаты добавляют проверки, а не повторяют старые 58/13.','',
    '## 12. Почему Beeline казался стабильнее и какие данные закроют вопрос','',
    'Разница пока является наблюдением владельца: позднее Beeline описан как 80–90, ранний baseline — примерно 70–80; Meganet иногда 85–93, а иногда 120–180 и выше. Это не контролируемое сравнение провайдеров. Более высокая пропускная способность не гарантирует меньший RTT. Нельзя вычислить ни постоянную «надбавку Meganet», ни долю времени в плохом состоянии по цензурированному журналу.','',
    'Круг неопределённости сужен: **одна лишь постоянная географическая длина маршрута не объясняет колебания внутри подключения; один общий постоянно перегруженный участок также недостаточен для разных классов совпадений.** Но путь конкретного UDP может деградировать без изменения контрольных ICMP; высокий Network RTT также может включать временную обработку/ответ приложения в зависимости от определения метрики. Утверждение «контроли хорошие, значит провайдер исправен» так же необоснованно, как «RETN ответил поздно, значит он виноват».','',
    '1. **Riot:** поддерживаемый числовой экспорт хотя бы 1 Гц: Network RTT avg/max, RTT+Processing Delay, jitter, loss in/out, client frame time, server/network processing, endpoint/ingress/backend mapping. Запросить определения и smoothing/reset/порог выдачи logger текущей сборки. В приватном канале Riot может сопоставить match IDs, которые исключены из публичного пакета. Это различит wire/path, обработки и артефакт фазы/logger.','',
    '2. **Meganet/транзит:** по указанным UTC и направлениям — egress/peering/ECMP/BNG/CGNAT, QoS и очереди/drop, route changes, обратные пути к абоненту и сопоставление по реальному NAT 5-tuple. Нужен WAN/NAT абонента в приватном канале от владельца; IP:порт назначения сам по себе недостаточен. Это различит общий путь и специфический UDP-поток.','',
    '3. **Пользователь в отдельном согласованном этапе:** Ethernet/Wi-Fi A/B на одном Meganet и том же игровом контексте; если Beeline доступен — сопоставимые чередующиеся серии на одном ПК и типе доступа, с фактическими endpoint и временем. Одинаковый публичный IP Riot не гарантирует одинаковый backend. Менять доступ автоматически или во время текущего матча не требуется.','',
    '4. **Безопасная полнота 90–119,99:** сначала запросить штатный экспорт у Riot. Если его нет, согласовать видимые штатные графики и запись пользователем с часами/словесными диапазонами; при необходимости отдельно обсудить поддерживаемую запись экрана/OCR. Не использовать инъекции, память процесса, Vanguard bypass или произвольный захват UDP. Текущий этап ничего из этого не включает.','',
    '5. **Очереди/локальная обработка:** при отдельном согласовании получить агрегированные WAN/airtime/retry/queue counters роутера и DPC/ISR/frame-time трассу без содержимого пользовательского трафика. Если после Ethernet сохраняется game-only RTT при нормальной обработке клиента, приоритет переходит к UDP пути/ingress/backend, а не к Wi-Fi.','',
    '## 13. Полная таблица найденных числовых точек','',
    'Все строки Average Ping, включая >180. UTC и полные окна в JSON; время ниже +05. QUIET означает ниже сохранённых контрольных лимитов, не нулевую UDP-потерю. N/A — недостаточное покрытие. Warnings — количество зарегистрированных L=burst_loss / Q=queue_overflow (включая сообщения об окончании) / I=input-stop / F=framerate; не число потерянных пакетов. У всех строк исходный baseline и continuous duration неизвестны. Номера строк и SHA позволяют Riot сверить оригинал, не публикуя токены/имена.','',
    '| Point | Время +05 | Average Ping мс | Conn / удалённый IP:порт | Класс ±4с | L/Q/I/F ±4с | Источник:строка |','|---|---|---:|---|---|---|---|']
    for e in points:
        ct=Counter(w['kind'] for w in e['warnings_4s']);counts='/'.join(str(ct[k]) for k in ['burst_loss','queue_overflow','input_replication_stopped','framerate_threshold'])
        label=CLASS.get(e['control_class_4s'],e['control_class_4s'])
        lines.append(f"| {e['point_id']} | {stamp(e['time_utc'])} | {e['value']:.2f} | {e['connection_id']} / {e['endpoint']} | {label} | {counts} | {aliases[e['file']]}:{e['line']} |")
    lines += ['', '## 14. Воспроизведение, проверки и публикация','',
    'Офлайн-анализ использует только проверенные технические поля. Порядок: `python scripts/analyze_rtt_open.py analyze`, затем `python scripts/write_rtt_open_report.py`; графики — headless `Render-InvestigationCharts.ps1` из chart-specs, HTML — `export_final_html.py`. `prepare` читает локальные исходники только для нового среза; для точного повторения опубликованных результатов достаточно committed inputs старого и нового дополнений. В `source-lineage.json` указан предыдущий private commit и фиксированные источники.','',
    'Тесты проверяют сохранение кластеров/числа выбранных циклов при rotate, объединение перекрывающейся экспозиции, удержание >180 внутри полного кластера, воспроизводимость reference, квантиль и нативный 12-byte layout на синтетическом буфере. Нативный API, GUI и сеть тестами не вызываются. Независимая сверка всех 263 прежних классов встроена в анализ. В renderer исправлен отдельный дефект первого headless paint: расчёт перенесённой легенды мог смещать точки относительно сетки; предварительный рендер в память стабилизирует layout перед PNG-экспортом. Числовые данные этим не изменены. Все восемь новых графиков сверены визуально; прежние шесть band-графиков пересохранены тем же исправленным renderer. Результаты повторного replay, integrity и privacy/secret checks зафиксированы в [VALIDATION.json](evidence/rtt-open-2026-11-15/VALIDATION.json).','',
    'В приватную и публичную версии входят отчёты без секретов, числовые поля, необходимые endpoint/порты, маршрутизаторы, временные метки, технические SHA, AP-псевдонимы и графики. Полные RRT/ShooterGame, account/match identifiers, авторизация, имена игроков, URL query, raw Windows/wlan messages, SSID/MAC/GUID, клиентские LAN/WAN и личная таблица замен не публикуются. Необезличенные оригиналы остаются локально; проверенные производные сохранены в приватной ветке.','',
    'Краткие проекты технических запросов: [Riot](RIOT-SUPPORT-RTT-OPEN-BRIEF.md) и [Meganet](MEGANET-RTT-OPEN-BRIEF.md). Они не отправлены. Старые опубликованные ZIP не перезаписаны; исправления доступны в текущих файлах и отдельном новом дополнении. Остановка монитора и изменения сетевых/игровых настроек не выполнялись.','']
    (reports/'VALORANT-RTT-OPEN-INVESTIGATION.md').write_text('\n'.join(lines),encoding='utf-8',newline='\n')
    charts(project,data,inputs)
    print(f'Wrote report with {len(points)} rows and 8 chart specs')


